   249  static inline uint16_t read_u16(const void *_data)
   250  {
   251      const unsigned char *data = _data;
   252
   253      return (data[0] & 0xffU) << 8 | (data[1] & 0xffU);
   254  }
   255
   256  static inline uint32_t read_u32(const void *_data)
   257  {
   258      const unsigned char *data = _data;
   259
   260      return (data[0] & 0xffUL) << 24 | (data[1] & 0xffUL) << 16 |
   261             (data[2] & 0xffUL) << 8  | (data[3] & 0xffUL);
   262  }
   263
   264  static inline int32_t read_s32(const void *_data)
   265  {
   266      const unsigned char *data = _data;
   267
   268      int32_t ret;
   269      uint32_t val = (data[0] & 0xffUL) << 24 | (data[1] & 0xffUL) << 16 |
   270                     (data[2] & 0xffUL) << 8  | (data[3] & 0xffUL);
   271
   272      memcpy(&ret, &val, 4);
   273
   274      return ret;
   275  }
