   285  static inline int read_data(spng_ctx *ctx, size_t bytes)
   286  {
   287      if(ctx == NULL) return 1;
   288      if(!bytes) return 0;
   289
   290      if(ctx->streaming && (bytes > ctx->data_size))
   291      {
   292          void *buf = spng__realloc(ctx, ctx->data, bytes);
   293          if(buf == NULL) return SPNG_EMEM;
   294
   295          ctx->data = buf;
   296          ctx->data_size = bytes;
   297      }
   298
   299      int ret;
   300      ret = ctx->read_fn(ctx, ctx->read_user_ptr, ctx->data, bytes);
   301      if(ret) return ret;
   302
   303      ctx->bytes_read += bytes;
   304      if(ctx->bytes_read < bytes) return SPNG_EOVERFLOW;
   305
   306      return 0;
   307  }
