   376  /* Read chunk bytes and update crc */
   377  static int read_chunk_bytes(spng_ctx *ctx, uint32_t bytes)
   378  {
   379      if(ctx == NULL) return 1;
   380      if(!bytes) return 0;
   381      if(bytes > ctx->cur_chunk_bytes_left) return 1; /* XXX: more specific error? */
   382
   383      int ret;
   384
   385      ret = read_data(ctx, bytes);
   386      if(ret) return ret;
   387
   388      if(is_critical_chunk(&ctx->current_chunk) &&
   389         ctx->crc_action_critical == SPNG_CRC_USE) goto skip_crc;
   390      else if(ctx->crc_action_ancillary == SPNG_CRC_USE) goto skip_crc;
   391
   392      ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, ctx->data, bytes);
   393
   394  skip_crc:
   395      ctx->cur_chunk_bytes_left -= bytes;
   396
   397      return ret;
   398  }
