  1192              uint16_t mask = ~0;
  1193              if(ctx->ihdr.bit_depth < 16) mask = (1 << ctx->ihdr.bit_depth) - 1;
  1194
  1195              if(ctx->ihdr.color_type == 0 || ctx->ihdr.color_type == 4)
  1196              {
  1197                  if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
  1198
  1199                  ctx->bkgd.gray = read_u16(data) & mask;
  1200              }
  1201              else if(ctx->ihdr.color_type == 2 || ctx->ihdr.color_type == 6)
  1202              {
  1203                  if(chunk.length != 6) return SPNG_ECHUNK_SIZE;
  1204
  1205                  ctx->bkgd.red = read_u16(data) & mask;
  1206                  ctx->bkgd.green = read_u16(data + 2) & mask;
  1207                  ctx->bkgd.blue = read_u16(data + 4) & mask;
  1208              }
  1209              else if(ctx->ihdr.color_type == 3)
  1210              {
  1211                  if(chunk.length != 1) return SPNG_ECHUNK_SIZE;
  1212                  if(!ctx->file_plte) return SPNG_EBKGD_NO_PLTE;
  1213
  1214                  memcpy(&ctx->bkgd.plte_index, data, 1);
  1215                  if(ctx->bkgd.plte_index >= ctx->plte.n_entries) return SPNG_EBKGD_PLTE_IDX;
  1216              }
  1217
  1218              ctx->file_bkgd = 1;
  1219              ctx->stored |= SPNG_CHUNK_BKGD;
  1220          }
  1221          else if(!memcmp(chunk.type, type_trns, 4))
  1222          {
  1223              if(ctx->file_plte && chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
  1224              if(ctx->file_trns) return SPNG_EDUP_TRNS;
  1225              if(!chunk.length) return SPNG_ECHUNK_SIZE;
  1226
  1227              uint16_t mask = ~0;
  1228              if(ctx->ihdr.bit_depth < 16) mask = (1 << ctx->ihdr.bit_depth) - 1;
  1229
  1230              if(ctx->ihdr.color_type == 0)
  1231              {
  1232                  if(chunk.length != 2) return SPNG_ECHUNK_SIZE;
  1233
  1234                  ctx->trns.gray = read_u16(data) & mask;
  1235              }
  1236              else if(ctx->ihdr.color_type == 2)
  1237              {
  1238                  if(chunk.length != 6) return SPNG_ECHUNK_SIZE;
  1239
  1240                  ctx->trns.red = read_u16(data) & mask;
  1241                  ctx->trns.green = read_u16(data + 2) & mask;
  1242                  ctx->trns.blue = read_u16(data + 4) & mask;
  1243              }
  1244              else if(ctx->ihdr.color_type == 3)
  1245              {
  1246                  if(chunk.length > ctx->plte.n_entries) return SPNG_ECHUNK_SIZE;
  1247                  if(!ctx->file_plte) return SPNG_ETRNS_NO_PLTE;
  1248
  1249                  size_t k;
  1250                  for(k=0; k < chunk.length; k++)
  1251                  {
  1252                      memcpy(&ctx->trns.type3_alpha[k], data + k, 1);
  1253                  }
  1254                  ctx->trns.n_type3_entries = chunk.length;
  1255              }
  1256              else return SPNG_ETRNS_COLOR_TYPE;
  1257
  1258              ctx->file_trns = 1;
  1259              ctx->stored |= SPNG_CHUNK_TRNS;
  1260          }
  1261          else if(!memcmp(chunk.type, type_hist, 4))
  1262          {
  1263              if(!ctx->file_plte) return SPNG_EHIST_NO_PLTE;
  1264              if(chunk.offset < ctx->plte_offset) return SPNG_ECHUNK_POS;
  1265              if(ctx->file_hist) return SPNG_EDUP_HIST;
  1266
  1267              if( (chunk.length / 2) != (ctx->plte.n_entries) ) return SPNG_ECHUNK_SIZE;
  1268
  1269              size_t k;
  1270              for(k=0; k < (chunk.length / 2); k++)
  1271              {
  1272                  ctx->hist.frequency[k] = read_u16(data + k*2);
  1273              }
  1274
  1275              ctx->file_hist = 1;
  1276              ctx->stored |= SPNG_CHUNK_HIST;
  1277          }
  1278          else if(!memcmp(chunk.type, type_phys, 4))
  1279          {
  1280              if(ctx->file_phys) return SPNG_EDUP_PHYS;
  1281
  1282              if(chunk.length != 9) return SPNG_ECHUNK_SIZE;
  1283
  1284              ctx->phys.ppu_x = read_u32(data);
  1285              ctx->phys.ppu_y = read_u32(data + 4);
  1286              memcpy(&ctx->phys.unit_specifier, data + 8, 1);
  1287
  1288              if(check_phys(&ctx->phys)) return SPNG_EPHYS;
  1289
  1290              ctx->file_phys = 1;
  1291              ctx->stored |= SPNG_CHUNK_PHYS;
  1292          }
  1293          else if(!memcmp(chunk.type, type_splt, 4))
  1294          {
  1295              if(ctx->user_splt) continue; /* XXX: should check profile names for uniqueness */
  1296              if(!chunk.length) return SPNG_ECHUNK_SIZE;
  1297
  1298              ctx->file_splt = 1;
  1299
  1300              if( !(ctx->stored & SPNG_CHUNK_SPLT) )
  1301              {
  1302                  ctx->n_splt = 1;
  1303                  ctx->splt_list = spng__calloc(ctx, 1, sizeof(struct spng_splt));
  1304                  if(ctx->splt_list == NULL) return SPNG_EMEM;
  1305              }
  1306              else
  1307              {
  1308                  ctx->n_splt++;
  1309                  if(ctx->n_splt < 1) return SPNG_EOVERFLOW;
  1310                  if(sizeof(struct spng_splt) > SIZE_MAX / ctx->n_splt) return SPNG_EOVERFLOW;
  1311
  1312                  void *buf = spng__realloc(ctx, ctx->splt_list, ctx->n_splt * sizeof(struct spng_splt));
  1313                  if(buf == NULL) return SPNG_EMEM;
  1314                  ctx->splt_list = buf;
  1315                  memset(&ctx->splt_list[ctx->n_splt - 1], 0, sizeof(struct spng_splt));
  1316              }
  1317
  1318              uint32_t i = ctx->n_splt - 1;
  1319
  1320              size_t keyword_len = chunk.length > 80 ? 80 : chunk.length;
  1321              char *keyword_nul = memchr(data, '\0', keyword_len);
  1322              if(keyword_nul == NULL) return SPNG_ESPLT_NAME;
  1323
  1324              memcpy(&ctx->splt_list[i].name, data, keyword_len);
  1325
  1326              if(check_png_keyword(ctx->splt_list[i].name)) return SPNG_ESPLT_NAME;
  1327
  1328              keyword_len = strlen(ctx->splt_list[i].name);
  1329
  1330              if( (chunk.length - keyword_len - 1) ==  0) return SPNG_ECHUNK_SIZE;
  1331
  1332              memcpy(&ctx->splt_list[i].sample_depth, data + keyword_len + 1, 1);
  1333
  1334              if(ctx->n_splt > 1)
  1335              {
  1336                  uint32_t j;
  1337                  for(j=0; j < i; j++)
  1338                  {
  1339                      if(!strcmp(ctx->splt_list[j].name, ctx->splt_list[i].name)) return SPNG_ESPLT_DUP_NAME;
  1340                  }
  1341              }
  1342
  1343              if(ctx->splt_list[i].sample_depth == 16)
  1344              {
  1345                  if( (chunk.length - keyword_len - 2) % 10 != 0) return SPNG_ECHUNK_SIZE;
  1346                  ctx->splt_list[i].n_entries = (chunk.length - keyword_len - 2) / 10;
  1347              }
  1348              else if(ctx->splt_list[i].sample_depth == 8)
  1349              {
  1350                  if( (chunk.length - keyword_len - 2) % 6 != 0) return SPNG_ECHUNK_SIZE;
  1351                  ctx->splt_list[i].n_entries = (chunk.length - keyword_len - 2) / 6;
  1352              }
  1353              else return SPNG_ESPLT_DEPTH;
  1354
  1355              if(ctx->splt_list[i].n_entries == 0) return SPNG_ECHUNK_SIZE;
  1356              if(sizeof(struct spng_splt_entry) > SIZE_MAX / ctx->splt_list[i].n_entries) return SPNG_EOVERFLOW;
  1357
  1358              ctx->splt_list[i].entries = spng__malloc(ctx, sizeof(struct spng_splt_entry) * ctx->splt_list[i].n_entries);
  1359              if(ctx->splt_list[i].entries == NULL) return SPNG_EMEM;
  1360
  1361              const unsigned char *splt = data + keyword_len + 2;
  1362
  1363              size_t k;
  1364              if(ctx->splt_list[i].sample_depth == 16)
  1365              {
  1366                  for(k=0; k < ctx->splt_list[i].n_entries; k++)
  1367                  {
  1368                      ctx->splt_list[i].entries[k].red = read_u16(splt + k * 10);
  1369                      ctx->splt_list[i].entries[k].green = read_u16(splt + k * 10 + 2);
  1370                      ctx->splt_list[i].entries[k].blue = read_u16(splt + k * 10 + 4);
  1371                      ctx->splt_list[i].entries[k].alpha = read_u16(splt + k * 10 + 6);
  1372                      ctx->splt_list[i].entries[k].frequency = read_u16(splt + k * 10 + 8);
  1373                  }
  1374              }
  1375              else if(ctx->splt_list[i].sample_depth == 8)
  1376              {
  1377                  for(k=0; k < ctx->splt_list[i].n_entries; k++)
  1378                  {
  1379                      uint8_t red, green, blue, alpha;
  1380                      memcpy(&red,   splt + k * 6, 1);
  1381                      memcpy(&green, splt + k * 6 + 1, 1);
  1382                      memcpy(&blue,  splt + k * 6 + 2, 1);
  1383                      memcpy(&alpha, splt + k * 6 + 3, 1);
  1384                      ctx->splt_list[i].entries[k].frequency = read_u16(splt + k * 6 + 4);
  1385
  1386                      ctx->splt_list[i].entries[k].red = red;
  1387                      ctx->splt_list[i].entries[k].green = green;
  1388                      ctx->splt_list[i].entries[k].blue = blue;
  1389                      ctx->splt_list[i].entries[k].alpha = alpha;
  1390                  }
  1391              }
  1392
  1393              ctx->stored |= SPNG_CHUNK_SPLT;
  1394          }
  1395          else if(!memcmp(chunk.type, type_time, 4))
  1396          {
  1397              if(ctx->file_time) return SPNG_EDUP_TIME;
  1398
  1399              if(chunk.length != 7) return SPNG_ECHUNK_SIZE;
  1400
  1401              struct spng_time time;
  1402
  1403              time.year = read_u16(data);
  1404              memcpy(&time.month, data + 2, 1);
  1405              memcpy(&time.day, data + 3, 1);
  1406              memcpy(&time.hour, data + 4, 1);
  1407              memcpy(&time.minute, data + 5, 1);
  1408              memcpy(&time.second, data + 6, 1);
  1409
  1410              if(check_time(&time)) return SPNG_ETIME;
  1411
  1412              ctx->file_time = 1;
  1413
  1414              if(!ctx->user_time) memcpy(&ctx->time, &time, sizeof(struct spng_time));
  1415
  1416              ctx->stored |= SPNG_CHUNK_TIME;
  1417          }
  1418          else if(!memcmp(chunk.type, type_text, 4) ||
  1419                  !memcmp(chunk.type, type_ztxt, 4) ||
  1420                  !memcmp(chunk.type, type_itxt, 4))
  1421          {
  1422              ctx->file_text = 1;
  1423
  1424              continue; /* XXX: https://gitlab.com/randy408/libspng/issues/31 */
  1425          }
  1426          else if(!memcmp(chunk.type, type_offs, 4))
  1427          {
  1428              if(ctx->file_offs) return SPNG_EDUP_OFFS;
  1429
  1430              if(chunk.length != 9) return SPNG_ECHUNK_SIZE;
  1431
  1432              ctx->offs.x = read_s32(data);
  1433              ctx->offs.y = read_s32(data + 4);
  1434              memcpy(&ctx->offs.unit_specifier, data + 8, 1);
  1435
  1436              if(check_offs(&ctx->offs)) return SPNG_EOFFS;
  1437
  1438              ctx->file_offs = 1;
  1439              ctx->stored |= SPNG_CHUNK_OFFS;
  1440          }
  1441          else if(!memcmp(chunk.type, type_exif, 4))
  1442          {
  1443              if(ctx->file_exif) return SPNG_EDUP_EXIF;
  1444
  1445              ctx->file_exif = 1;
  1446
  1447              if(!chunk.length) return SPNG_EEXIF;
  1448
  1449              struct spng_exif exif;
  1450
  1451              exif.data = spng__malloc(ctx, chunk.length);
  1452              if(exif.data == NULL) return SPNG_EMEM;
  1453
  1454              memcpy(exif.data, data, chunk.length);
  1455              exif.length = chunk.length;
  1456
  1457              if(check_exif(&exif))
  1458              {
  1459                  spng__free(ctx, exif.data);
  1460                  return SPNG_EEXIF;
  1461              }
  1462
  1463              if(!ctx->user_exif) memcpy(&ctx->exif, &exif, sizeof(struct spng_exif));
  1464              else spng__free(ctx, exif.data);
  1465
  1466              ctx->stored |= SPNG_CHUNK_EXIF;
  1467          }
  1468      }
  1469
  1470      return ret;
  1471  }
